const state={answers:{},history:[],index:0,visible:[]};
const sections=[
  {id:'company',label:'Profilo aziendale'},
  {id:'usage',label:'Domanda AI'},
  {id:'architecture',label:'Architettura & dati'},
  {id:'risk',label:'Governance & delivery'},
  {id:'economics',label:'Economics'}
];
const Q=[
{id:'company',section:'company',type:'text',title:'Partiamo dalla vostra organizzazione.',help:'Nome azienda o business unit. Serve solo per personalizzare il risultato.',placeholder:'Es. SCS Consulting',optional:true},
{id:'sector',section:'company',type:'single',title:'In quale settore operate principalmente?',help:'Il settore modifica il livello atteso di governance, sicurezza e controllo.',options:[['professional','Servizi professionali','Consulenza, studi, B2B'],['finance','Banche / assicurazioni','Contesti ad alta regolamentazione'],['public','PA / sanità','Dati e processi pubblici o sanitari'],['industry','Industria / utilities','Operations, supply chain, field service'],['retail','Retail / consumer','Marketing, vendite, customer care'],['tech','Tech / digital','Prodotto, software, data & AI'],['other','Altro','Configurazione neutra']]},
{id:'employees',section:'company',type:'number',title:'Quante persone lavorano nell’organizzazione?',help:'Inserisci il numero complessivo di dipendenti o collaboratori stabili.',min:1,max:200000,suffix:'persone'},
{id:'aiUsers',section:'company',type:'number',title:'Quante persone potrebbero usare davvero l’AI?',help:'Non tutti i dipendenti devono necessariamente avere accesso. Indica gli utenti potenziali realistici nel primo anno.',min:1,max:200000,suffix:'utenti',validate:(v)=>!state.answers.employees||Number(v)<=Number(state.answers.employees)||'Gli utenti AI non possono superare il totale indicato.'},
{id:'departments',section:'usage',type:'multi',title:'Dove si concentrerà l’utilizzo?',help:'Seleziona tutte le aree che useranno l’AI in modo significativo.',options:[['management','Management','Decisioni, sintesi, scenario analysis'],['sales','Sales & marketing','Offerte, contenuti, lead, analisi'],['operations','Operations','Processi, qualità, supply chain'],['support','Customer service','Ticket, assistenza, knowledge'],['financehr','Finance / HR / Legal','Documenti, controllo, persone'],['it','IT / sviluppo','Coding, analisi, automazioni'],['consulting','Consulenza / knowledge work','Ricerca, deliverable, analisi']]},
{id:'intensity',section:'usage',type:'single',title:'Quanto entrerà l’AI nella giornata lavorativa?',help:'Usiamo questa risposta per stimare frequenza, carico e fabbisogno di capacità.',options:[['light','Occasionale','Poche attività alla settimana'],['normal','Quotidiana','Alcune interazioni ogni giorno'],['high','Frequente','Parte stabile di molte attività'],['embedded','Core workflow','Sempre presente nei processi principali']]},
{id:'workloads',section:'usage',type:'multi',title:'Che tipo di lavoro farà l’AI?',help:'Seleziona i carichi che rappresentano davvero il vostro caso.',options:[['text','Testi & comunicazione','Email, sintesi, documenti'],['docs','Documenti complessi','Contratti, manuali, report lunghi'],['data','Dati & analisi','Excel, BI, tabelle, forecasting'],['code','Codice & IT','Sviluppo, test, documentazione'],['customer','Customer interaction','Chat, ticket, supporto'],['media','Immagini / audio / video','Contenuti multimodali'],['workflow','Workflow operativi','Azioni su sistemi e processi']]},
{id:'ambition',section:'architecture',type:'single',title:'Quale livello di AI state immaginando?',help:'Questa è la variabile che pesa di più sull’architettura e sul costo iniziale.',options:[['assistant','Assistente AI','Aiuta le persone a scrivere, analizzare e ragionare'],['knowledge','AI aziendale','Usa documenti e conoscenza interna'],['integrated','AI integrata','Legge dati e dialoga con sistemi aziendali'],['agents','Agenti AI','Esegue attività e parti di processo']]},
{id:'deployment',section:'architecture',type:'single',title:'Come pensate di utilizzare l’AI?',help:'Se non avete ancora deciso, scegli “Ibrido / da definire”.',options:[['saas','Licenze enterprise','ChatGPT, Copilot, Claude o equivalenti'],['custom','Applicazioni AI custom','Soluzioni sviluppate via API'],['hybrid','Ibrido / da definire','Licenze + applicazioni / agenti']]},
{id:'integrations',section:'architecture',type:'single',when:()=>['integrated','agents'].includes(state.answers.ambition)||((state.answers.workloads||[]).includes('workflow')),title:'Quanti sistemi dovranno comunicare con l’AI?',help:'Conta CRM, ERP, documentale, ticketing, database, software proprietari e altri sistemi rilevanti.',options:[['1','1–2 sistemi','Integrazione circoscritta'],['4','3–5 sistemi','Ecosistema medio'],['8','6–10 sistemi','Ecosistema articolato'],['14','Oltre 10','Architettura enterprise complessa']]},
{id:'integrationTypes',section:'architecture',type:'multi',when:()=>Number(state.answers.integrations||0)>0,title:'Quali sistemi sono coinvolti?',help:'Serve a distinguere integrazioni standard da integrazioni più costose o legacy.',options:[['m365','Microsoft 365 / Google','Email, file, collaboration'],['crm','CRM / ticketing','Salesforce, Dynamics, ServiceNow…'],['erp','ERP / SAP','Processi core e dati gestionali'],['db','Database / DWH','SQL, lakehouse, BI'],['dms','Documentale','SharePoint, DMS, knowledge'],['legacy','Legacy / software proprietario','API limitate o integrazioni ad hoc']]},
{id:'dataScope',section:'architecture',type:'single',when:()=>state.answers.ambition!=='assistant',title:'Quanto deve conoscere l’AI della vostra azienda?',help:'Più i dati sono distribuiti, dinamici o sensibili, più cresce il lavoro di data engineering e controllo.',options:[['docs','Documenti selezionati','Manuali, policy, PDF, procedure'],['manydocs','Knowledge estesa','Molti repository e documenti'],['systems','Dati dai sistemi','CRM, ERP, database, analytics'],['realtime','Dati quasi real-time','Informazioni aggiornate continuamente']]},
{id:'dataQuality',section:'architecture',type:'single',when:()=>state.answers.ambition!=='assistant',title:'Quanto sono già ordinati e accessibili i dati?',help:'Non chiediamo di caricare nulla. Ci serve solo capire quanto lavoro preparatorio potrebbe servire.',options:[['high','Molto ordinati','Fonti note, permessi chiari, buona qualità'],['medium','Abbastanza ordinati','Qualche silo o duplicazione'],['low','Frammentati','Molti file, fonti e regole diverse'],['unknown','Non lo sappiamo','Serve una discovery iniziale']]},
{id:'autonomy',section:'architecture',type:'single',when:()=>state.answers.ambition==='agents',title:'Quanto potere avranno gli agenti AI?',help:'L’autonomia incide su testing, audit, permessi, supervisione e monitoraggio.',options:[['suggest','Suggeriscono','Nessuna azione sui sistemi'],['prepare','Preparano','Una persona approva ogni output'],['approve','Agiscono con approvazione','Tool use dopo un consenso'],['autonomous','Agiscono in autonomia','Alcune azioni senza approvazione preventiva']]},
{id:'agentVolume',section:'architecture',type:'single',when:()=>state.answers.ambition==='agents',title:'Quante attività automatiche potrebbero eseguire ogni giorno?',help:'Una stima per ordine di grandezza è sufficiente.',options:[['100','Meno di 100','Volumi iniziali'],['500','100–1.000','Adozione significativa'],['3000','1.000–5.000','Operatività ad alto volume'],['10000','Oltre 5.000','Scala enterprise']]},
{id:'sensitivity',section:'risk',type:'single',title:'Che tipo di informazioni potrà trattare l’AI?',help:'Non servono dettagli: ci interessa solo il livello di sensibilità.',options:[['public','Informazioni pubbliche','Rischio contenuto'],['internal','Informazioni interne','Uso aziendale non pubblico'],['confidential','Informazioni confidenziali','Dati commerciali o strategici'],['personal','Dati personali','Clienti, dipendenti, utenti'],['regulated','Dati altamente regolamentati','Finanziari, sanitari o equivalenti']]},
{id:'criticality',section:'risk',type:'single',title:'Quanto sono critici i processi coinvolti?',help:'Un errore su una bozza email non ha lo stesso impatto di un errore su un processo core.',options:[['low','Bassa','Output facilmente verificabili'],['medium','Media','Impatto operativo limitato'],['high','Alta','Impatto economico o cliente rilevante'],['mission','Mission critical','Processi core, continuità o compliance']]},
{id:'team',section:'risk',type:'single',title:'Quanta capacità AI avete già internamente?',help:'Considera persone che sanno progettare, integrare, governare o mettere in produzione soluzioni AI.',options:[['none','Nessun team dedicato','Dipendenza alta da partner esterni'],['small','1–2 persone','Presidio iniziale'],['medium','3–5 persone','Capability interna concreta'],['strong','Team strutturato','Engineering, data, security, product']]},
{id:'timeline',section:'risk',type:'single',title:'Quanto velocemente volete arrivare in produzione?',help:'La velocità comprime discovery, sviluppo, change e governance: un rollout aggressivo costa di più.',options:[['pilot','Pilot prima, poi scala','Approccio progressivo'],['3m','Entro 3 mesi','Time-to-value prioritario'],['6m','3–6 mesi','Percorso bilanciato'],['12m','6–12 mesi','Rollout graduale']]},
{id:'useCases',section:'economics',type:'single',title:'Quanti use case volete portare realmente in produzione nel primo anno?',help:'Conta i casi d’uso distinti che devono essere implementati, testati e gestiti.',options:[['2','1–2','Focus su pochi casi ad alto valore'],['4','3–5','Portafoglio selettivo'],['8','6–10','Programma AI strutturato'],['14','Oltre 10','Scala enterprise']]},
{id:'support',section:'economics',type:'single',title:'Che modello di gestione immaginate dopo il go-live?',help:'Il costo ricorrente dipende da quanto supporto, monitoraggio e miglioramento continuo rimarranno attivi.',options:[['light','Presidio leggero','Supporto su richiesta'],['managed','Gestione condivisa','Team interno + partner'],['full','Managed service','Monitoraggio e ottimizzazione continuativi'],['internal','Quasi tutto interno','Il partner interviene solo su evolutive']]},
{id:'currentSpend',section:'economics',type:'single',title:'State già spendendo per strumenti AI?',help:'Serve per leggere meglio il delta economico. Se non è noto, scegli “Non sappiamo”.',options:[['0','No / quasi nulla','Partenza da zero'],['25','Fino a €25k / anno','Adozione iniziale'],['100','€25k–100k / anno','Adozione già significativa'],['250','Oltre €100k / anno','Portafoglio già attivo'],['unknown','Non sappiamo','Dato non disponibile']]},
{id:'contact',section:'economics',type:'text',title:'Ultimo passaggio: chi sta compilando?',help:'Nome o ruolo del referente. Non viene inviato a servizi esterni: resta nel report generato sul dispositivo.',placeholder:'Es. CFO / Head of Innovation',optional:true}
];
const $=s=>document.querySelector(s); const $$=s=>Array.from(document.querySelectorAll(s));
const fmt=n=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Math.round(n));
const compact=n=>{if(n>=1e6)return '€'+(n/1e6).toLocaleString('it-IT',{maximumFractionDigits:1})+'M'; if(n>=1e3)return '€'+Math.round(n/1e3).toLocaleString('it-IT')+'k'; return fmt(n)};
function visibleQuestions(){return Q.filter(q=>!q.when||q.when())}
function refreshVisible(){state.visible=visibleQuestions(); if(state.index>=state.visible.length)state.index=state.visible.length-1}
function show(id){$$('.screen').forEach(x=>x.classList.remove('active'));$('#'+id).classList.add('active')}
function renderRail(){const q=state.visible[state.index]; const secIdx=sections.findIndex(s=>s.id===q.section); $('#railLabel').textContent=sections[secIdx].label; $('#railSteps').innerHTML=sections.map((s,i)=>`<div class="rail-step ${i===secIdx?'active':''}"><i></i><span>${s.label}</span></div>`).join(''); $('#railNumber').textContent=String(state.index+1).padStart(2,'0'); $('#progress').style.width=((state.index)/Math.max(1,state.visible.length)*100)+'%';}
function optionIndex(i){return String(i+1).padStart(2,'0')}
function renderQuestion(){refreshVisible(); const q=state.visible[state.index]; renderRail(); let body=`<div class="q-kicker">${sections.find(s=>s.id===q.section).label}</div><h2 class="q-title">${q.title}</h2><p class="q-help">${q.help||''}</p>`;
if(q.type==='single'||q.type==='multi'){const selected=q.type==='multi'?(state.answers[q.id]||[]):[state.answers[q.id]]; body+=`<div class="answers">${q.options.map((o,i)=>{const on=selected.includes(o[0]);return `<button class="answer ${on?'selected':''}" data-value="${o[0]}"><div class="a-top"><span class="a-index">${optionIndex(i)}</span><span class="check">${on?'✓':''}</span></div><div class="a-title">${o[1]}</div><div class="a-desc">${o[2]}</div></button>`}).join('')}</div>`;}
if(q.type==='number'){body+=`<div class="numeric-card"><input class="number-input" id="numberInput" type="number" inputmode="numeric" min="${q.min||0}" max="${q.max||999999}" placeholder="0" value="${state.answers[q.id]??''}"/><div class="numeric-hint"><span>${q.suffix||''}</span><span>Inserisci un valore realistico</span></div></div>`;}
if(q.type==='text'){body+=`<input class="text-input" id="textInput" type="text" maxlength="100" placeholder="${q.placeholder||''}" value="${(state.answers[q.id]||'').replace(/"/g,'&quot;')}"/>${q.optional?'<div class="note">Campo facoltativo.</div>':''}`;}
$('#questionContent').innerHTML=body; $('#backBtn').style.visibility=state.index===0?'hidden':'visible'; $('#nextBtn').textContent=state.index===state.visible.length-1?'Calcola la stima →':'Continua →';
$$('.answer').forEach(el=>{el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect();el.style.setProperty('--x',(e.clientX-r.left)+'px');el.style.setProperty('--y',(e.clientY-r.top)+'px')}); el.onclick=()=>selectOption(q,el.dataset.value)});
const ni=$('#numberInput');if(ni)ni.addEventListener('input',()=>state.answers[q.id]=ni.value); const ti=$('#textInput');if(ti)ti.addEventListener('input',()=>state.answers[q.id]=ti.value.trim());
}
function selectOption(q,val){if(q.type==='single'){state.answers[q.id]=val; renderQuestion(); setTimeout(()=>{if(state.visible[state.index]?.id===q.id) next();},180);}else{let arr=state.answers[q.id]||[]; arr=arr.includes(val)?arr.filter(x=>x!==val):[...arr,val]; state.answers[q.id]=arr;renderQuestion();} save();}
function validateCurrent(){const q=state.visible[state.index],v=state.answers[q.id];if(q.optional)return true;if(q.type==='multi'&&(!v||!v.length))return shake('Seleziona almeno una voce.');if(q.type==='single'&&!v)return shake('Seleziona una risposta.');if(q.type==='number'&&(!v||Number(v)<q.min||Number(v)>q.max))return shake('Inserisci un valore valido.');if(q.validate){const r=q.validate(v);if(r!==true)return shake(typeof r==='string'?r:'Controlla il valore inserito.')}return true}
function shake(msg){const c=$('#questionContent');c.animate([{transform:'translateX(0)'},{transform:'translateX(-7px)'},{transform:'translateX(7px)'},{transform:'translateX(0)'}],{duration:280});toast(msg);return false}
function next(){if(!validateCurrent())return;refreshVisible(); if(state.index>=state.visible.length-1){calculate();return} state.history.push(state.visible[state.index].id);state.index++;save();renderQuestion();window.scrollTo({top:0,behavior:'smooth'})}
function back(){if(state.index<=0)return;state.index--;save();renderQuestion();window.scrollTo({top:0,behavior:'smooth'})}
function save(){localStorage.setItem('scs-ai-cost-assessment',JSON.stringify({answers:state.answers,index:state.index}))}
function load(){try{const s=JSON.parse(localStorage.getItem('scs-ai-cost-assessment'));if(s){state.answers=s.answers||{};state.index=s.index||0}}catch(e){}}
function riskMultiplier(){let m=1; if(['finance','public'].includes(state.answers.sector))m+=.08; if(['personal','regulated'].includes(state.answers.sensitivity))m+=state.answers.sensitivity==='regulated'?.14:.08; if(['high','mission'].includes(state.answers.criticality))m+=state.answers.criticality==='mission'?.12:.07; return m}
function integrationCount(){return Number(state.answers.integrations||0)}
